-- Table structure for `english_exercises`
CREATE TABLE IF NOT EXISTS `english_exercises` (
  `id` int NOT NULL AUTO_INCREMENT,
  `exercise_hash` char(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `level` enum('Basic','Intermediate','Expert','Advanced') COLLATE utf8mb4_unicode_ci DEFAULT 'Basic',
  `kategori` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pertanyaan` longtext COLLATE utf8mb4_unicode_ci,
  `pilihan_a` longtext COLLATE utf8mb4_unicode_ci,
  `pilihan_b` longtext COLLATE utf8mb4_unicode_ci,
  `pilihan_c` longtext COLLATE utf8mb4_unicode_ci,
  `pilihan_d` longtext COLLATE utf8mb4_unicode_ci,
  `jawaban_benar` char(1) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pembahasan` longtext COLLATE utf8mb4_unicode_ci,
  `media_type` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `media_url` text COLLATE utf8mb4_unicode_ci,
  `sort_order` int DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_exercise_hash` (`exercise_hash`),
  UNIQUE KEY `uq_english_exercise_hash` (`exercise_hash`),
  KEY `idx_level` (`level`),
  KEY `idx_kategori` (`kategori`),
  KEY `idx_active` (`is_active`),
  KEY `idx_english_exercise_level` (`level`),
  KEY `idx_english_exercise_kategori` (`kategori`),
  KEY `idx_english_exercise_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

