INSERT IGNORE INTO `english_exercises` (`id`, `exercise_hash`, `level`, `kategori`, `pertanyaan`, `pilihan_a`, `pilihan_b`, `pilihan_c`, `pilihan_d`, `jawaban_benar`, `pembahasan`, `media_type`, `media_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('1','4fc91794bcf45026dd43670c4eca58dc','Basic','Parts of Speech','Parts of Speech Which word is a noun?','Quickly','Teacher','Blue','Run','B','Teacher adalah noun karena menunjukkan orang','','','1','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('2','6a0b635e98d83978b3a8cb515a2e46ed','Basic','Verb','V2 dari \"go\" adalah?','Gone','Went','Going','Goes','B','Go adalah irregular verb: go-went-gone.','','','2','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('3','97b64eefc9857755cc008f78ef553717','Basic','Vocabulary','What is \"apel\" in English?','Apple','Book','Chair','Walk','A','Apel dalam bahasa Inggris adalah Apple.','image','','3','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('4','71f02dd5a13f9d65acab2dc7f3c2c667','Basic','Vocabulary','What is the name of this pictures','Rhinocuros','Rhinoceres','Rhinocoros','Rhinoceros','D','Bahasa Inggris dari badak adalah \"Rhinoceros\"','Image','https://mudamudiselor.web.id/lat-inggris/assets/images/Rhinoceros.jpg','4','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('5','97d827cfeeeddaf0e7d25780b8e84e28','Basic','Parts of Speech','Which word is a verb?','Happy','Table','Sleep','Green','C','Sleep adalah verb karena menunjukkan aksi.','','','5','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('6','453d34b582a617d246cf4b5cf5a4a298','Basic','Parts of Speech','Which word is an adjective?','Beautiful','Slowly','Under','Book','A','Beautiful adalah adjective karena menjelaskan noun.','','','6','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('7','f3edfa0a64e9dc202ee0e7acc27a4401','Basic','Parts of Speech','Which word is an adverb?','House','Quickly','Student','Red','B','Quickly adalah adverb karena menjelaskan cara melakukan aksi.','','','7','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('8','44aecb753ccb69331168bca78bb209aa','Basic','Parts of Speech','Which word is a preposition?','And','But','Under','Wow','C','Under adalah preposition karena menunjukkan posisi.','','','8','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('9','f5876eada8c1b9e99ed9983d44379512','Basic','Parts of Speech','Which word is a conjunction?','Because','Table','Happy','Run','A','Because adalah conjunction karena menghubungkan ide.','','','9','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('10','cf7db7363b5e3fe0a7e27c1fc56a7e2d','Basic','Parts of Speech','Which word is an interjection?','Wow!','Book','Teacher','Slow','A','Wow adalah interjection karena menunjukkan ekspresi.','','','10','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('11','b8f0d1d31f309754a33b98e1df0ddf8b','Basic','Parts of Speech','Which word names a place?','School','Beautiful','Quickly','Eat','A','School adalah noun karena menunjukkan tempat.','','','11','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('12','d556825959a9a7d872af00b16d130b65','Basic','Parts of Speech','Which word describes a noun?','Run','Red','Under','Slowly','B','Red menjelaskan noun sehingga termasuk adjective.','','','12','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('13','f3e94ab2e50e9e20df91c2c237e03e26','Basic','Parts of Speech','Which word connects two words?','And','Chair','Walk','Yellow','A','And adalah conjunction.','','','13','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('14','f0d8a8383872347172bf5c40507c98bc','Basic','Parts of Speech','Which word is a person?','Table','Teacher','Fast','Blue','B','Teacher adalah noun untuk orang.','','','14','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('15','bbcbd3641c249b7b3d9b1f53a3942b15','Intermediate','Grammar','Choose the correct sentence, below','She go to school every day','She goes to school every day','She going to school every day','She gone to school every day','B','Subject \"She\" memakai verb+s/es dalam Simple Present.','','','15','1','2026-07-07 12:01:07','2026-07-07 12:03:28'),('16','6525320a8d3be38471747428c5e5b3a3','Expert','Grammar','Choose the sentence with the correct conditional structure.','If I studied harder, I would pass the exam.','If I study harder, I would passed the exam.','If I studied harder, I will passing the exam.','If I studies harder, I would pass the exam.','A','Second conditional memakai pola: If + past simple, would + base verb.','','','16','1','2026-07-07 12:01:07','2026-07-07 12:03:28');
