-- Table structure for `english_materi`
CREATE TABLE IF NOT EXISTS `english_materi` (
  `id` int NOT NULL AUTO_INCREMENT,
  `chapter_id` int DEFAULT NULL,
  `materi_key` varchar(150) COLLATE utf8mb4_unicode_ci NOT NULL,
  `title` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `tipe_rumus` varchar(150) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rumus` longtext COLLATE utf8mb4_unicode_ci,
  `pembahasan` longtext COLLATE utf8mb4_unicode_ci,
  `arti` longtext COLLATE utf8mb4_unicode_ci,
  `link_visual` text COLLATE utf8mb4_unicode_ci,
  `kata_kunci` longtext COLLATE utf8mb4_unicode_ci,
  `penjelasan` longtext COLLATE utf8mb4_unicode_ci,
  `description` longtext COLLATE utf8mb4_unicode_ci,
  `notes_json` longtext COLLATE utf8mb4_unicode_ci,
  `patterns_json` longtext COLLATE utf8mb4_unicode_ci,
  `quiz_json` longtext COLLATE utf8mb4_unicode_ci,
  `video_type` enum('none','youtube','embed','upload','url','local') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'none',
  `video_url` text COLLATE utf8mb4_unicode_ci,
  `sort_order` int NOT NULL DEFAULT '0',
  `is_active` tinyint(1) NOT NULL DEFAULT '1',
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_english_materi_key` (`materi_key`),
  KEY `idx_english_materi_chapter` (`chapter_id`),
  CONSTRAINT `fk_english_materi_chapter` FOREIGN KEY (`chapter_id`) REFERENCES `english_materi_chapters` (`id`) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

SET @column_exists := (SELECT COUNT(*) FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'english_materi' AND COLUMN_NAME = 'id');
