INSERT IGNORE INTO `english_materi` (`id`, `chapter_id`, `materi_key`, `title`, `tipe_rumus`, `rumus`, `pembahasan`, `arti`, `link_visual`, `kata_kunci`, `penjelasan`, `description`, `notes_json`, `patterns_json`, `quiz_json`, `video_type`, `video_url`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES ('1',NULL,'pos-noun','Noun','pos-noun','','','','','Noun adalah salah satu kelas kata (part of speech utama yang berfungsi untuk menamai atau mengidentifikasi seseorang, tempat, benda, hewan, ide, atau konsep abstrak. Noun merupakan elemen dasar yang paling sering menjadi subjek atau objek dalam sebuah struktur kalimat.','','',NULL,NULL,NULL,'none',NULL,'1','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('2',NULL,'pos-pronoun','Pronoun','pos-pronoun','','','','','Pronoun adalah kata yang digunakan untuk menggantikan kata benda (noun atau frasa kata benda. Fungsinya adalah menghindari pengulangan kata yang monoton dalam kalimat, sehingga komunikasi menjadi lebih efektif dan nyaman dibaca maupun didengar','','',NULL,NULL,NULL,'none',NULL,'2','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('3',NULL,'pos-verb','Verb','pos-verb','','','','','Verb secara umum adalah kata yang digunakan untuk menunjukkan suatu tindakan (action, kejadian (event, atau keadaan (state of being yang dilakukan atau dialami oleh subjek. Dalam sebuah kalimat, verb berfungsi sebagai inti utama yang menjelaskan apa yang sedang dilakukan oleh subjek tersebut.','','',NULL,NULL,NULL,'none',NULL,'3','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('4',NULL,'pos-adjective','Adjective','pos-adjective','','','','','Adjective (adjektiva atau kata sifat adalah kelas kata yang berfungsi untuk mendeskripsikan, menjelaskan, atau membatasi kata benda (noun atau kata ganti oun. Kata sifat membuat objek yang dijelaskan menjadi lebih spesifik atau memberi informasi mengenai sifat, ukuran, warna, jumlah, dan kualitasnya','','',NULL,NULL,NULL,'none',NULL,'4','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('5',NULL,'pos-adverb','Adverb','pos-adverb','','','','','Adverb (kata keterangan adalah kelas kata yang berfungsi untuk memodifikasi atau memberikan informasi tambahan mengenai cara, tempat, waktu, atau tingkat suatu kejadian. Kata ini biasanya digunakan untuk menjelaskan kata kerja (verb, kata sifat (adjective, atau adverb lainnya','','',NULL,NULL,NULL,'none',NULL,'5','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('6',NULL,'pos-preposition','Preposition','pos-preposition','','','','','preposition (preposisi atau kata depan adalah kata yang diletakkan sebelum kata benda (noun atau kata ganti oun. Fungsinya untuk menunjukkan hubungan antara kata tersebut dengan elemen lain di dalam kalimat, seperti waktu, lokasi, arah, atau posisi.','','',NULL,NULL,NULL,'none',NULL,'6','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('7',NULL,'pos-conjunction','Conjunction','pos-conjunction','','','','','Conjunction (kata hubung atau konjungsi adalah bagian dari part of speech yang berfungsi untuk menghubungkan kata, frasa (kelompok kata, klausa (bagian kalimat, atau kalimat menjadi satu kesatuan yang padu','','',NULL,NULL,NULL,'none',NULL,'7','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('8',NULL,'pos-interjection','Interjection','pos-interjection','','','','','Interjection (atau kata seru adalah kata atau frasa yang digunakan untuk mengekspresikan emosi atau perasaan yang kuat secara spontan. Kata ini tidak memiliki hubungan tata bahasa (gramatikal dengan kata lain di dalam kalimat dan sering kali diikuti oleh tanda seru (!.','','',NULL,NULL,NULL,'none',NULL,'8','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('9',NULL,'bab1-pronouns','Tabel Pronouns','bab1-pronouns','','','','','','','',NULL,NULL,NULL,'none',NULL,'9','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('10',NULL,'bab1-subject-verb','subject-verb-agreement','bab1-subject-verb','','','','','Regular dan irregular verb adalah dua jenis kata kerja (verb dalam bahasa Inggris yang dibedakan berdasarkan cara perubahannya saat digunakan dalam bentuk lampau (past tense atau verb 2 dan bentuk partisipel (past participle atau verb 3.','','',NULL,NULL,NULL,'none',NULL,'10','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('11',NULL,'bab1-regular-verbs','Regular dan Irreguler Verb','bab1-regular-verbs','','','','','','','',NULL,NULL,NULL,'none',NULL,'11','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('12',NULL,'aktif-positif','Past Future Perfect Continuous','aktif-positif','Subject + Would + Have + Been + V-ing + Object + Adverb','We would have been living here for three years by 2025','','','','','We would have been living here for three years by 2025',NULL,NULL,NULL,'none',NULL,'81','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('13',NULL,'aktif-negatif','Past Future Perfect Continuous','aktif-negatif','Subject + Would + Not + Have + Been + V-ing + Object + Adverb','We would not have been living here for three years by 2025','','','','','We would not have been living here for three years by 2025',NULL,NULL,NULL,'none',NULL,'82','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('14',NULL,'aktif-tanya','Past Future Perfect Continuous','aktif-tanya','Would + Subject + Have + Been + V-ing + Onject + Adverb + ?','Would you have been living here for three years by 2025 ?','','','','','Would you have been living here for three years by 2025 ?',NULL,NULL,NULL,'none',NULL,'83','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('15',NULL,'aktif-positif-nominal','Past Future Perfect Nominal','aktif-positif-nominal','Subject + Would + Have + Been + Complement','He would have been a doctor if he passed the exam','','','','','He would have been a doctor if he passed the exam',NULL,NULL,NULL,'none',NULL,'78','0','2026-07-07 12:01:07','2026-07-07 18:40:35'),('16',NULL,'aktif-negatif-nominal','Past Future Perfect Nominal','aktif-negatif-nominal','Subject + Would + Not + Have + Been + Complement','He would not have been a doctor if he failed the exam','','','','','He would not have been