-- Table structure for `english_verbs`
CREATE TABLE IF NOT EXISTS `english_verbs` (
  `id` int NOT NULL AUTO_INCREMENT,
  `verb_hash` char(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `v1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v3` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `v_ing` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `arti` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `tipe` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `level` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_verb_hash` (`verb_hash`),
  UNIQUE KEY `uq_english_verb_hash` (`verb_hash`),
  KEY `idx_tipe` (`tipe`),
  KEY `idx_level` (`level`),
  KEY `idx_active` (`is_active`),
  KEY `idx_english_verb_tipe` (`tipe`),
  KEY `idx_english_verb_level` (`level`),
  KEY `idx_english_verb_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

