-- Table structure for `english_vocabulary`
CREATE TABLE IF NOT EXISTS `english_vocabulary` (
  `id` int NOT NULL AUTO_INCREMENT,
  `vocab_hash` char(32) COLLATE utf8mb4_unicode_ci NOT NULL,
  `abjad` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `indonesia` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `inggris` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `pengucapan` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `kategori` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `level` varchar(100) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `sort_order` int DEFAULT '0',
  `is_active` tinyint(1) DEFAULT '1',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_vocab_hash` (`vocab_hash`),
  UNIQUE KEY `uq_english_vocab_hash` (`vocab_hash`),
  KEY `idx_abjad` (`abjad`),
  KEY `idx_kategori` (`kategori`),
  KEY `idx_level` (`level`),
  KEY `idx_active` (`is_active`),
  KEY `idx_english_vocab_abjad` (`abjad`),
  KEY `idx_english_vocab_kategori` (`kategori`),
  KEY `idx_english_vocab_level` (`level`),
  KEY `idx_english_vocab_active` (`is_active`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

